<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Вход — ПрофиСпорт</title><link rel="stylesheet" href="../styles.css"><body><main class="checkoutPage"><h1>Вход в управление магазином</h1><form id="loginForm"><label>Пользователь<input name="username" autocomplete="username" required value="Иван Кириллов 414"></label><label>Пароль<input name="password" type="password" autocomplete="current-password" required></label><button>Войти</button><p id="loginMsg" role="status"></p></form><a href="../index.html">Вернуться в магазин</a></main><script>
const form=document.getElementById('loginForm'),msg=document.getElementById('loginMsg');
form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('button');button.disabled=true;msg.textContent='Входим…';try{const r=await fetch('../server/api.php?action=login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});if(!r.ok)throw Error(r.status===401?'Неверный пользователь или пароль.':'Не удалось войти. Повторите попытку.');location.href='index.php'}catch(e){msg.textContent=e.message;button.disabled=false}};
</script></body></html>
